import pytest; from src.extraction.extension.service import ExtractionError, ExtractionService
class TestCSVParsing:
    def setup_method(self): self.service = ExtractionService()
    async def test_parse_dbs_csv(self): 'AC-extraction.1.2'; csv_content = b'Transaction Date,Reference,Debit Amount,Credit Amount,Transaction Ref1,Transaction Ref2,Transaction Ref3\n15 Jan 2025,REF001,,500.00,SALARY,EMPLOYER PTE LTD,JAN 2025\n16 Jan 2025,REF002,100.00,,NETS,FAIRPRICE,GROCERIES\n17 Jan 2025,REF003,50.00,,ATM WITHDRAWAL,DBS ATM,'; result = await self.service._parse_csv_content(csv_content, 'DBS'); assert 'currency' not in result; assert 'period_start' not in result; assert 'period_end' not in result; assert result['observed_transaction_start'] == '2025-01-15'; assert result['observed_transaction_end'] == '2025-01-17'; assert len(result['transactions']) == 3; txn0 = result['transactions'][0]; assert txn0['date'] == '2025-01-15'; assert txn0['amount'] == '500.00'; assert txn0['direction'] == 'IN'; assert 'SALARY' in txn0['description']; txn1 = result['transactions'][1]; assert txn1['direction'] == 'OUT'; assert txn1['amount'] == '100.00'; _m1_csv_content = b'Statement Currency,Statement Period Start,Statement Period End,Statement Opening Balance,Statement Closing Balance,Date,Description,Amount\nSGD,2025-01-01,2025-01-31,100.00,125.00,2025-01-15,Interest,25.00'; _m1_result = await self.service._parse_csv_content(_m1_csv_content, 'Example Bank'); assert _m1_result['currency'] == 'SGD'; assert _m1_result['period_start'] == '2025-01-01'; assert _m1_result['period_end'] == '2025-01-31'; assert _m1_result['opening_balance'] == '100.00'; assert _m1_result['closing_balance'] == '125.00'
    async def test_AC_extraction_2476_1_declared_csv_balances_are_not_marked_missing(self): 'AC-extraction.2476.1'; declared = b'Statement Currency,Statement Period Start,Statement Period End,Statement Opening Balance,Statement Closing Balance,Date,Description,Amount\nSGD,2025-01-01,2025-01-31,100.00,125.00,2025-01-15,Interest,25.00'; result = await self.service._parse_csv_content(declared, 'Example Bank'); assert result['balance_source'] == 'declared_in_csv_export'; closing_only = b'Statement Currency,Statement Closing Balance,Date,Description,Amount\nSGD,125.00,2025-01-15,Interest,25.00'; result = await self.service._parse_csv_content(closing_only, 'Example Bank'); assert result['balance_source'] == 'missing_from_csv_export'; no_balances = b'Date,Description,Amount\n2025-01-15,Interest,25.00'; result = await self.service._parse_csv_content(no_balances, 'Example Bank'); assert result['balance_source'] == 'missing_from_csv_export'; _m2_csv_content = b'Transaction Date,Debit Amount,Credit Amount,Transaction Ref1\n20 Jan 2025,,1000.00,TRANSFER FROM SAVINGS\n21 Jan 2025,200.00,,BILL PAYMENT'; _m2_result = await self.service._parse_csv_content(_m2_csv_content, 'POSB'); assert len(_m2_result['transactions']) == 2; assert _m2_result['transactions'][0]['direction'] == 'IN'; assert _m2_result['transactions'][1]['direction'] == 'OUT'
    async def test_parse_wise_csv(self): 'AC-extraction.1.3'; csv_content = b'ID,Created on,Direction,Source amount (after fees),Reference\n12345,2025-01-10T10:30:00Z,OUT,250.00,Payment to vendor\n12346,2025-01-12T14:00:00Z,IN,1500.00,Client payment received'; result = await self.service._parse_csv_content(csv_content, 'Wise'); assert len(result['transactions']) == 2; assert result['observed_transaction_start'] == '2025-01-10'; assert result['observed_transaction_end'] == '2025-01-12'; assert 'period_start' not in result; assert 'period_end' not in result; assert result['transactions'][0]['direction'] == 'OUT'; assert result['transactions'][0]['amount'] == '250.00'; assert result['transactions'][1]['direction'] == 'IN'; assert result['transactions'][1]['amount'] == '1500.00'; _m3_csv_content = b'Transaction Date,Description,Debit,Credit\n05/01/2025,SALARY CREDIT,,5000.00\n06/01/2025,CREDIT CARD PAYMENT,1500.00,'; _m3_result = await self.service._parse_csv_content(_m3_csv_content, 'OCBC'); assert len(_m3_result['transactions']) == 2; assert _m3_result['transactions'][0]['direction'] == 'IN'; assert _m3_result['transactions'][1]['direction'] == 'OUT'
    async def test_parse_generic_csv_with_amount_column(self):
        'AC-extraction.1.4'; csv_content = b'Date,Description,Amount\n2025-01-01,Income,500.00\n2025-01-02,Expense,-100.00'; result = await self.service._parse_csv_content(csv_content, 'Unknown Bank'); assert len(result['transactions']) == 2; assert result['transactions'][0]['direction'] == 'IN'; assert result['transactions'][0]['amount'] == '500.00'; assert result['transactions'][1]['direction'] == 'OUT'; assert result['transactions'][1]['amount'] == '100.00'; _m4_csv_content = b'Transaction Date,Amount\n'
        with pytest.raises(ExtractionError, match='(No valid transactions|empty or has no data rows)'): await self.service._parse_csv_content(_m4_csv_content, 'DBS')
    async def test_parse_csv_with_bom(self): 'AC-extraction.1.5'; csv_content = b'\xef\xbb\xbfTransaction Date,Debit Amount,Credit Amount,Description\n15 Jan 2025,,100.00,Test'; result = await self.service._parse_csv_content(csv_content, 'DBS'); assert len(result['transactions']) == 1; assert result['transactions'][0]['amount'] == '100.00'; _m5_csv_content = b'Date,Amount,Description\n2025-01-15,100.00,ISO format\n15/01/2025,200.00,DD/MM/YYYY format\n01/15/2025,300.00,MM/DD/YYYY format'; _m5_result = await self.service._parse_csv_content(_m5_csv_content, 'Generic'); assert len(_m5_result['transactions']) == 3; _m6_csv_content = b'Date,Debit,Credit,Description\n2025-01-15,$50.00,,Purchase\n2025-01-16,,SGD 100.00,Deposit'; _m6_result = await self.service._parse_csv_content(_m6_csv_content, 'Generic'); assert len(_m6_result['transactions']) == 2; assert _m6_result['transactions'][0]['amount'] == '50.00'; assert _m6_result['transactions'][1]['amount'] == '100.00'; _m7_csv_content = b'Date,Credit,Description\n2025-01-15,"1,500.00",Large deposit'; _m7_result = await self.service._parse_csv_content(_m7_csv_content, 'Generic'); assert len(_m7_result['transactions']) == 1; assert _m7_result['transactions'][0]['amount'] == '1500.00'; _m8_csv_content = b'Transaction Date,Debit Amount,Credit Amount,Description\n15 Jan 2025,,100.00,Valid transaction\nInvalid Date,,50.00,Should be skipped\n16 Jan 2025,,200.00,Another valid one'; _m8_result = await self.service._parse_csv_content(_m8_csv_content, 'DBS'); assert len(_m8_result['transactions']) == 2
